<?php require 'config.php'; if(current_user()) redirect('index.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';
 if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$error='Enter a name, valid email and password with at least 8 characters.';}
 else{try{$s=$pdo->prepare('INSERT INTO users(name,email,phone,password_hash) VALUES(?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);flash('Account created successfully. Please log in.');redirect('login.php');}catch(PDOException $e){$error='That email may already be registered.';}}
}
$page_title='Create account';require 'partials/header.php';?>
<section class="panel narrow"><span class="eyebrow">YOUR NEXT ADVENTURE</span><h1>Create account</h1><p class="muted">Join us and keep all your trip requests in one place.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Full name</label><input name="name" required maxlength="100" autocomplete="name"></div><div class="field"><label>Email address</label><input type="email" name="email" required autocomplete="email"></div><div class="field"><label>Phone (optional)</label><input name="phone" autocomplete="tel"></div><div class="field"><label>Password (minimum 8 characters)</label><input type="password" name="password" required minlength="8" autocomplete="new-password"></div><button class="btn btn-primary full">Create account ↗</button></form><p class="muted" style="margin-top:18px">Already registered? <a href="login.php"><b>Log in</b></a></p></section><?php require 'partials/footer.php';?>
